ripple.source:
// concentric ripple, height colour map with contours, sin(x) drawn on top
Ir77FieldPoint Field(Ir77FieldIn f) {
    float amplitude = f.params[0], wavelength = f.params[1], speed = f.params[2];
    float h = amplitude * cos(6.2831853 / wavelength * (length(f.coord.xy) - speed * f.time));
    return Ir77FieldPoint(vec3(f.coord.x, h, f.coord.y), 0.0, vec4(1.0), vec4(h, 0.0, 0.0, 0.0));
}

vec4 Paint(vec2 c, float t, float p[8]) {
    return vec4(1.0, 1.0, 1.0, Ir77Line(Ir77Curve(c.y, sin(c.x * 2.0 + t)), 2.0));
}

lorenz.source:
// Lorenz attractor -- every particle integrates from where it was last frame
Ir77FieldPoint Field(Ir77FieldIn f) {
    Ir77FieldPoint p = f.prev;
    if (f.first) {
        p.position = vec3(Ir77Random(f.id, 1u), Ir77Random(f.id, 2u), Ir77Random(f.id, 3u)) * 2.0 - 1.0;
        p.size = 0.03;
        p.color = vec4(0.4, 0.7, 1.0, 0.15);
    }

    float s = f.params[0], r = f.params[1], b = f.params[2], scale = f.params[3];
    vec3 x = p.position / scale;
    vec3 dx = vec3(s * (x.y - x.x), x.x * (r - x.z) - x.y, x.x * x.y - b * x.z);

    p.position += dx * min(f.dt, 0.02) * scale;
    p.data.x = length(dx);   // speed -> colour map
    return p;
}

orbital.source:
// hydrogen 2p_z orbital -- a jittered grid, density in opacity and colour
Ir77FieldPoint Field(Ir77FieldIn f) {
    vec3 jitter = vec3(Ir77Random(f.id, 4u), Ir77Random(f.id, 5u), Ir77Random(f.id, 6u)) - 0.5;
    vec3 r = f.coord + jitter * 0.15;

    float d = length(r);
    float psi = r.z * exp(-d * 0.5);
    float density = psi * psi;

    return Ir77FieldPoint(r.xzy, 0.04, vec4(1.0, 0.5, 0.2, clamp(density * f.params[0], 0.0, 1.0)), vec4(density, 0.0, 0.0, 0.0));
}

spirograph.source:
// spirograph -- a flat sheet as the canvas, a hypotrochoid tracing into it
Ir77FieldPoint Field(Ir77FieldIn f) {
    return Ir77FieldPoint(vec3(f.coord.x, 0.0, f.coord.y), 0.0, vec4(0.05, 0.05, 0.07, 1.0), vec4(0.0));
}

vec2 Pen(uint pen, float t, float p[8]) {
    float R = p[0], r = p[1], d = p[2];
    return vec2((R - r) * cos(t) + d * cos((R - r) / r * t), (R - r) * sin(t) - d * sin((R - r) / r * t));
}

oscilloscope.source:
// oscilloscope -- two channels sweeping left to right, phosphor fade
Ir77FieldPoint Field(Ir77FieldIn f) {
    return Ir77FieldPoint(vec3(f.coord.x, 0.0, f.coord.y), 0.0, vec4(0.02, 0.04, 0.02, 1.0), vec4(0.0));
}

vec2 Pen(uint pen, float t, float p[8]) {
    return pen == 0u ? vec2(0.0, 2.0 * sin(t * p[0])) : vec2(0.0, 1.0 * sin(t * p[1] + 1.0) + 0.5 * sin(t * p[0] * 3.0));
}
